const http=require('http'),fs=require('fs'),path=require('path');http.createServer((req,res)=>{const files={'/':'index.html','/management':'management.html','/management.js':'management.js','/termweek':'termweek.html','/termweek.js':'termweek.js','/workspace-extension.js':'workspace-extension.js','/workspace-polish.css':'workspace-polish.css','/workspace-polish.js':'workspace-polish.js','/operational-panel.js':'operational-panel.js','/operational-panel.css':'operational-panel.css'};const f=files[req.url.split('?')[0]];if(!f){res.writeHead(404);return res.end('Not found')}res.setHeader('Content-Type',f.endsWith('.js')?'text/javascript; charset=utf-8':f.endsWith('.css')?'text/css; charset=utf-8':'text/html; charset=utf-8');res.end(fs.readFileSync(path.join(__dirname,f)))}).listen(9467,'0.0.0.0');